import cn from 'classnames';
import { IconsText, TextProps } from './text.types';

import './text.scss';

export function Text({ id, text, icon, className }: TextProps) {
  const iconCn = cn({
    'ds-brand-text--icon-call': icon === ('call' as IconsText),
    'ds-brand-text--icon-contact-mail': icon === ('contact_mail' as IconsText),
    'ds-brand-text--icon-email': icon === ('email' as IconsText),
    'ds-brand-text--icon-account': icon === ('account' as IconsText),
    'ds-brand-text--icon-language': icon === ('language' as IconsText),
    'ds-brand-text--icon-arrow-left': icon === ('arrow-left' as IconsText),
    'ds-brand-text--icon-arrow-right': icon === ('arrow-right' as IconsText),
    'ds-brand-text--icon-pin-drop': icon === ('pin-drop' as IconsText),
    'ds-brand-text--icon-3d-rotation': icon === ('3d-rotation' as IconsText),
    'ds-brand-text--icon-alarm': icon === ('alarm' as IconsText),
  });

  const withIconCn = icon && iconCn;

  return (
    <div className={cn('text', className, withIconCn)}>
      <div id={id} className="cmp-text" dangerouslySetInnerHTML={{ __html: text }}></div>
    </div>
  );
}

export default Text;
